 return {family,level:f.level,data:[f.cat,f.title,`${f.story} Que faites-vous ?`,opts.map(o=>[o.title,o.desc,o.effect,o.q===2?"réfléchi":"choix à nuancer"])],qualities:opts.map(o=>o.q),feedback:opts.map(o=>o.feedback),echoes:opts.map(o=>[[f.title,(/^Souvenez-vous/.test(o.echo)?o.echo:`Souvenez-vous : ${o.title.toLowerCase()}. ${o.echo}`),o.delta,"Les conséquences d'une décision ne se révèlent pas toujours immédiatement."]])};
